(function(E){ const x = E["exam-09"] = E["exam-09"] || {units:{}}; (x.units = x.units || {})["x09-r3"] = {"id":"x09-r3","patterns":["RA-mind","GT3-life","PARA-research","TR-NGvsF","TR-whosevoice","TR-samewords","TR-detail","TR-paraphrase","TR-limit","TR-plural"],"title":{"en":"Reading 3: Passage 3 / Section 3","tr":"Reading 3: Passage 3 / Section 3","fa":"Reading ۳: متن ۳ (Passage 3) / بخش ۳ (Section 3)"},"objective":{"en":"In this lesson you will learn to follow a writer’s argument: answer multiple choice questions on the research, complete a summary from a box of words, and decide YES, NO or NOT GIVEN on the writer’s views.","tr":"Bu derste bir yazarın argümanını takip etmeyi öğreneceksin: araştırmayla ilgili çoktan seçmeli soruları cevaplayacak, bir özeti kelime kutusundan tamamlayacak ve yazarın görüşleri için YES, NO ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری استدلال یک نویسنده را دنبال کنی: به سؤال‌های چندگزینه‌ای درباره‌ی پژوهش جواب بدهی، خلاصه‌ای را از یک کادر کلمه کامل کنی و درباره‌ی نظرهای نویسنده بین YES، NO و NOT GIVEN تصمیم بگیری."},"objectiveGT":{"en":"In this lesson you will learn to choose a heading for each paragraph of a long article, complete a summary with one word from the text, and answer multiple choice questions.","tr":"Bu derste uzun bir makalenin her paragrafına bir başlık seçmeyi, bir özeti metinden tek kelimeyle tamamlamayı ve çoktan seçmeli soruları cevaplamayı öğreneceksin.","fa":"در این درس یاد می‌گیری برای هر پاراگراف یک مقاله‌ی بلند عنوان انتخاب کنی، یک خلاصه را با یک کلمه از متن کامل کنی و به سؤال‌های چندگزینه‌ای جواب بدهی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 3: an argument based on research","tr":"Reading Passage 3: araştırmaya dayalı bir tartışma","fa":"Reading Passage 3: استدلالی بر پایه‌ی پژوهش"},"objective":{"en":"In this lesson you will learn to follow a writer’s argument: answer multiple choice questions on the research, complete a summary from a box of words, and decide YES, NO or NOT GIVEN on the writer’s views.","tr":"Bu derste bir yazarın argümanını takip etmeyi öğreneceksin: araştırmayla ilgili çoktan seçmeli soruları cevaplayacak, bir özeti kelime kutusundan tamamlayacak ve yazarın görüşleri için YES, NO ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری استدلال یک نویسنده را دنبال کنی: به سؤال‌های چندگزینه‌ای درباره‌ی پژوهش جواب بدهی، خلاصه‌ای را از یک کادر کلمه کامل کنی و درباره‌ی نظرهای نویسنده بین YES، NO و NOT GIVEN تصمیم بگیری."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"14"},{"label":{"en":"Box","tr":"Kutu","fa":"کادر"},"value":"A-J"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: why false rumours spread","tr":"Bu sınav: sahte söylentiler neden yayılır","fa":"این آزمون: چرا شایعه‌های دروغ پخش می‌شوند"},"intro":{"en":"Psychology, education and society make up one of the biggest groups of Academic topics. In Passage 3 the writer usually argues a position, so you must separate research findings from the writer’s opinions.","tr":"Psikoloji, eğitim ve toplum Academic konuların en büyük gruplarından birini oluşturur. Passage 3’te yazar genelde bir görüşü savunur; araştırma bulgularını yazarın görüşlerinden ayırmalısın.","fa":"روان‌شناسی، آموزش و جامعه یکی از بزرگ‌ترین گروه‌های موضوعی Academic است. در Passage 3 نویسنده معمولاً از یک دیدگاه دفاع می‌کند، پس باید یافته‌های پژوهش را از نظرهای نویسنده جدا کنی."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x09-r3-ctx","exam":true,"patterns":["RA-mind","PARA-research"],"often":{"pattern":"RA-mind","n":30,"of":120,"label":{"en":"Comes up often in the real exam: 30 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 30’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۳۰ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"An argument about how people think","tr":"İnsanların nasıl düşündüğü üzerine bir tartışma","fa":"بحثی درباره‌ی اینکه آدم‌ها چطور فکر می‌کنند"},"asks":{"en":"The writer uses psychology research to argue a position: why people believe and share false stories, how hard it is to correct them, and what might help. Multiple choice and a summary test the research; YES/NO/NOT GIVEN tests the writer’s own views.","tr":"Yazar bir görüşü savunmak için psikoloji araştırmalarını kullanıyor: insanlar neden sahte haberlere inanıp onları paylaşıyor, bunları düzeltmek neden zor ve ne işe yarayabilir. Çoktan seçmeli sorular ve özet araştırmayı ölçer; YES/NO/NOT GIVEN yazarın kendi görüşlerini ölçer.","fa":"نویسنده با کمک پژوهش‌های روان‌شناسی از دیدگاهی دفاع می‌کند: چرا آدم‌ها خبرهای دروغ را باور و پخش می‌کنند، چرا اصلاحشان سخت است و چه چیزی کمک می‌کند. سؤال‌های چندگزینه‌ای و خلاصه پژوهش را می‌سنجند؛ YES/NO/NOT GIVEN نظر خودِ نویسنده را."},"fields":["The writer’s position","Why people believe","Why corrections fail","A fear that proved wrong","Who believes","Solutions","The writer’s view on regulation"],"words":[{"a":"I believe","b":"it would be a mistake / seems to me","tr":"inanıyorum","fa":"باور دارم"},{"a":"repeated","b":"heard several times / familiar","tr":"tekrarlanmış","fa":"تکرارشده"},{"a":"believable","b":"convincing / feels true","tr":"inandırıcı","fa":"باورپذیر"},{"a":"correct","b":"deny / show to be false","tr":"düzeltmek","fa":"اصلاح کردن"},{"a":"continue to influence","b":"still affect / is still mentioned","tr":"etkilemeye devam etmek","fa":"همچنان اثر گذاشتن"},{"a":"rare","b":"uncommon / seldom happens","tr":"nadir","fa":"نادر"},{"a":"reflect","b":"stop to think / pause before reacting","tr":"düşünmek","fa":"تأمل کردن"},{"a":"accuracy","b":"whether something is true","tr":"doğruluk","fa":"درستی"},{"a":"promising","b":"likely to work / encouraging","tr":"umut verici","fa":"امیدبخش"},{"a":"I have serious doubts","b":"I am not convinced / I disagree","tr":"ciddi şüphelerim var","fa":"تردید جدی دارم"},{"a":"in advance","b":"before it arrives / beforehand","tr":"önceden","fa":"از قبل"},{"a":"it is often assumed","b":"many people think / a common belief","tr":"çoğu zaman varsayılır","fa":"اغلب فرض می‌شود"}],"traps":[{"en":"\"It is often assumed that...\" reports a common belief, usually so that the writer can disagree. It is not the writer’s view.","tr":"\"Çoğu zaman ... varsayılır\" yaygın bir inanışı aktarır, genelde yazarın karşı çıkabilmesi için. Bu yazarın görüşü değildir.","fa":"«اغلب فرض می‌شود که...» یک باور رایج را نقل می‌کند، معمولاً برای اینکه نویسنده با آن مخالفت کند. این نظر نویسنده نیست."},{"en":"\"Some argue that...\" followed by \"I have serious doubts\" means the writer disagrees: a statement of that argument is NO.","tr":"\"Bazıları ... diye savunur\" ardından \"ciddi şüphelerim var\" geliyorsa yazar katılmıyordur: o argümanı söyleyen ifade NO’dur.","fa":"«بعضی‌ها استدلال می‌کنند که...» و بعد «تردید جدی دارم» یعنی نویسنده مخالف است: جمله‌ای که آن استدلال را می‌گوید NO است."},{"en":"In a summary with a box, two words can fit the grammar. Choose the one that matches the meaning of that part of the passage.","tr":"Kutulu bir özette iki kelime dilbilgisine uyabilir. Metnin o kısmının anlamına uyanı seç.","fa":"در خلاصه‌ی کادردار ممکن است دو کلمه از نظر دستوری جور باشند. کلمه‌ای را انتخاب کن که با معنی همان بخش متن جور است."}],"example":{"text":"\"Many people believe that playing music to babies makes them cleverer. I see no good evidence for this.\"","item":"Statement: Playing music to babies improves their intelligence. (views of the writer)","answer":"NO","why":{"en":"\"Many people believe\" is not the writer; \"I see no good evidence\" shows the writer disagrees.","tr":"\"Many people believe\" yazar değil; \"iyi bir kanıt görmüyorum\" yazarın katılmadığını gösteriyor.","fa":"«خیلی‌ها باور دارند» نویسنده نیست؛ «هیچ شاهد خوبی نمی‌بینم» نشان می‌دهد نویسنده مخالف است."}}},{"id":"RA-mind-research","ctx":["RA-mind"],"title":{"en":"Research with named researchers","tr":"Adı geçen araştırmacılarla araştırma metinleri","fa":"پژوهش با پژوهشگرهای نام‌برده"},"asks":{"en":"A report that quotes several researchers or studies on one question: how habits form, why people believe false news, what makes people wise. Matching features asks who said or found what; sentence endings test causes and conclusions.","tr":"Tek bir soru üzerine birkaç araştırmacıdan ya da çalışmadan alıntı yapan bir rapor: alışkanlıklar nasıl oluşur, insanlar neden yanlış haberlere inanır, bilgeliği ne sağlar. Özellik eşleştirme kimin ne söylediğini ya da bulduğunu sorar; cümle sonları nedenleri ve sonuçları sınar.","fa":"گزارشی که درباره‌ی یک سؤال از چند پژوهشگر یا پژوهش نقل می‌کند: عادت‌ها چطور شکل می‌گیرند، چرا آدم‌ها خبر جعلی را باور می‌کنند، چه چیزی آدم را خردمند می‌کند. جورکردن ویژگی‌ها می‌پرسد چه کسی چه گفت یا چه یافت؛ پایان جمله‌ها علت‌ها و نتیجه‌ها را می‌سنجند."},"fields":["Which researcher suggests that rewards matter more than repetition?","Which study found that older people were less affected?","Habits form more quickly when... (sentence ending)","Why does the writer mention the 1990s experiment?"],"words":[{"a":"claims","b":"argues / maintains / insists","tr":"iddia eder","fa":"ادعا می‌کند"},{"a":"suggests","b":"proposes / puts forward the idea","tr":"öne sürer","fa":"مطرح می‌کند"},{"a":"found","b":"discovered / the results showed","tr":"buldu","fa":"دریافت"},{"a":"doubts","b":"is sceptical about / questions","tr":"şüphe eder","fa":"تردید دارد"},{"a":"agrees with","b":"supports / shares the view","tr":"katılır","fa":"موافق است با"},{"a":"disagrees with","b":"rejects / takes issue with","tr":"karşı çıkar","fa":"مخالف است با"},{"a":"a link between","b":"is connected to / is associated with","tr":"arasında bir bağ","fa":"ارتباطی میان"},{"a":"leads to","b":"causes / is responsible for","tr":"yol açar","fa":"منجر می‌شود به"},{"a":"earlier research","b":"previous studies","tr":"önceki araştırmalar","fa":"پژوهش‌های قبلی"},{"a":"overestimate","b":"think it is bigger than it is","tr":"olduğundan büyük sanmak","fa":"بیش از حد برآورد کردن"},{"a":"in the long run","b":"over time / eventually","tr":"uzun vadede","fa":"در درازمدت"},{"a":"to some extent","b":"only partly / in a limited way","tr":"bir ölçüde","fa":"تا حدی"}],"traps":[{"en":"Every mention counts: a researcher may be named in two places. Read both before you decide.","tr":"Her geçiş önemlidir: bir araştırmacının adı iki yerde geçebilir. Karar vermeden ikisini de oku.","fa":"هر اشاره مهم است: اسم یک پژوهشگر ممکن است دو جا بیاید. قبل از تصمیم هر دو را بخوان."},{"en":"A claim is an opinion; a finding is a result. \"Claims\" and \"has shown\" do not match.","tr":"İddia bir görüştür; bulgu bir sonuçtur. \"Claims\" ile \"has shown\" eşleşmez.","fa":"ادعا یک نظر است؛ یافته یک نتیجه. «claims» و «has shown» با هم جور نیستند."},{"en":"Sentence endings: two endings may fit the grammar, but only one matches the meaning.","tr":"Cümle sonları: iki son dilbilgisine uyabilir ama yalnızca biri anlama uyar.","fa":"پایان جمله‌ها: ممکن است دو پایان از نظر دستوری جور باشند، ولی فقط یکی با معنی جور است."}],"example":{"text":"Dr Lin found that people who repeated an action at the same time every day formed the habit faster. Professor Ross, however, argues that timing matters less than the reward people feel afterwards.","item":"Who believes that the reward is more important than the time of day?  A Dr Lin   B Professor Ross","answer":"B","why":{"en":"\"Timing matters less than the reward\" is Ross’s view. Lin’s finding is about timing.","tr":"\"Zamanlama ödülden daha az önemli\" Ross’un görüşü. Lin’in bulgusu zamanlamayla ilgili.","fa":"«زمان‌بندی کمتر از پاداش مهم است» نظر راس است. یافته‌ی لین درباره‌ی زمان‌بندی است."}},"track":"academic","general":true,"patterns":["RA-mind"],"often":{"pattern":"RA-mind","n":30,"of":120,"label":{"en":"Comes up often in the real exam: 30 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 30’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۳۰ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Choices, a word box, the writer’s views","tr":"Seçimler, bir kelime kutusu, yazarın görüşleri","fa":"گزینه‌ها، کادر کلمه، نظرهای نویسنده"},"body":{"en":"Questions 27-30: choose A, B, C or D. Questions 31-36: complete a summary with words from a box, A-J; four words are not used. Questions 37-40: YES, NO or NOT GIVEN on the writer’s views.","tr":"Soru 27-30: A, B, C ya da D’yi seç. Soru 31-36: bir özeti A-J kutusundaki kelimelerle tamamla; dört kelime kullanılmaz. Soru 37-40: yazarın görüşleri için YES, NO ya da NOT GIVEN.","fa":"سؤال‌های ۲۷ تا ۳۰: A، B، C یا D را انتخاب کن. سؤال‌های ۳۱ تا ۳۶: خلاصه را با کلمه‌های کادر (A تا J) کامل کن؛ چهار کلمه استفاده نمی‌شوند. سؤال‌های ۳۷ تا ۴۰: YES، NO یا NOT GIVEN درباره‌ی نظرهای نویسنده."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Mark the writer’s voice as you read: I believe, I have doubts, seems to me, this is good news.","tr":"Okurken yazarın sesini işaretle: I believe, I have doubts, seems to me, this is good news.","fa":"موقع خواندن صدای نویسنده را علامت بزن: I believe، I have doubts، seems to me، this is good news."},{"en":"For multiple choice, find the paragraph first, then read all four options against it.","tr":"Çoktan seçmelide önce paragrafı bul, sonra dört seçeneği ona göre oku.","fa":"در چندگزینه‌ای اول پاراگراف را پیدا کن و بعد هر چهار گزینه را با آن بسنج."},{"en":"For the box, decide the word class of each gap, then choose by meaning.","tr":"Kutu için her boşluğun kelime türüne karar ver, sonra anlama göre seç.","fa":"برای کادر، نوع کلمه‌ی هر جای خالی را مشخص کن و بعد بر اساس معنی انتخاب کن."},{"en":"For YES/NO/NOT GIVEN, ask: has the writer given a view on exactly this point?","tr":"YES/NO/NOT GIVEN için sor: yazar tam olarak bu nokta hakkında bir görüş bildirdi mi?","fa":"برای YES/NO/NOT GIVEN بپرس: آیا نویسنده درباره‌ی دقیقاً همین نکته نظری داده؟"}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"YES, NO or NOT GIVEN?","tr":"YES mi, NO mu, NOT GIVEN mı?","fa":"YES، NO یا NOT GIVEN؟"},"table":{"headers":{"en":["The writer","The answer"],"tr":["Yazar","Cevap"],"fa":["نویسنده","جواب"]},"rows":[["states the same view","YES"],["states the opposite view","NO"],["gives no view on this point","NOT GIVEN"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One view, step by step","tr":"Bir görüş, adım adım","fa":"یک نظر، قدم به قدم"},"instruction":"Do the following statements agree with the views of the writer?","text":"\"Some schools now ban phones completely. I understand why, but I think teaching students to use them well would be more useful.\"","item":"Statement: Schools should ban phones completely.","answer":"NO","walk":[{"en":"Find the writer’s voice: \"I understand why, but I think...\".","tr":"Yazarın sesini bul: \"I understand why, but I think...\".","fa":"صدای نویسنده را پیدا کن: «I understand why, but I think...»."},{"en":"\"Some schools ban\" is a fact, not the writer’s view.","tr":"\"Bazı okullar yasaklıyor\" bir gerçek, yazarın görüşü değil.","fa":"«بعضی مدرسه‌ها ممنوع می‌کنند» یک واقعیت است، نه نظر نویسنده."},{"en":"The writer prefers teaching good use, the opposite of a ban: NO.","tr":"Yazar iyi kullanımı öğretmeyi tercih ediyor, yasağın tersi: NO.","fa":"نویسنده آموزش استفاده‌ی درست را ترجیح می‌دهد، یعنی برعکسِ ممنوعیت: NO."}]},"quick":{"prompt":"Writer: \"Exams are often blamed for stress. I suspect the real cause is the lack of sleep before them.\" Statement: \"Lack of sleep may matter more than exams themselves.\"","options":["NO","YES","NOT GIVEN"],"correct":1,"why":{"en":"\"I suspect the real cause is the lack of sleep\" agrees with the statement.","tr":"\"Asıl nedenin uykusuzluk olduğundan şüpheleniyorum\" ifadeyle uyuşuyor.","fa":"«گمان می‌کنم علت اصلی کم‌خوابی است» با جمله هم‌خوان است."}},"remember":{"en":"Separate the research from the writer’s voice; for YES/NO, only the writer’s own view counts.","tr":"Araştırmayı yazarın sesinden ayır; YES/NO için yalnızca yazarın kendi görüşü sayılır.","fa":"پژوهش را از صدای نویسنده جدا کن؛ برای YES/NO فقط نظر خودِ نویسنده حساب است."},"type":"explain","id":"c-x09-r3-e","course":"ielts-exams","exam":"exam-09","unit":"x09-r3"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 3","title":{"en":"Why false rumours travel so fast","tr":"Sahte söylentiler neden bu kadar hızlı yayılıyor","fa":"چرا شایعه‌های دروغ این‌قدر سریع پخش می‌شوند"},"timed":20,"ctx":["RA-mind"],"intro":"You should spend about 20 minutes on Questions 27-40, which are based on Reading Passage 3 below.","passage":"Why false rumours travel so fast\n\nRumours are as old as language. Long before newspapers, false stories about neighbours, rulers and strangers passed from village to village, often changing a little at each telling. What is new is the speed and scale at which such stories now move. One large study of social media found that untrue stories spread further and faster than accurate ones, and that this was mainly because people chose to share them, not because of automated accounts. It is tempting to blame the technology, but I believe that would be a mistake. The platforms have certainly made the problem bigger; the habits of mind that drive it, however, are our own.\n\nThe first of these habits concerns familiarity. When we hear a claim several times, it begins to feel true, simply because it is easier to process. Psychologists have shown this effect in many experiments: statements that have been repeated are rated as more believable than new ones, even when participants have been told that some of them are false, and even when the statements contradict what they already know. Every time a rumour is passed on, therefore, it becomes a little more convincing to the next person who meets it.\n\nEmotion adds to the effect. Stories that surprise, frighten or anger us are more likely to be remembered and more likely to be shared. A dull but accurate report about a new medicine will rarely travel as far as a dramatic claim that the medicine is secretly dangerous. False stories have an advantage here, because they are not limited by the facts. Their authors can make them as shocking or as novel as they wish.\n\nThe most troubling finding, perhaps, is how hard it is to remove a false belief once it has formed. Researchers call this the continued influence of misleading information: even after people accept that a claim has been corrected, it often continues to influence their reasoning. In one typical experiment, participants read about a fire that was at first blamed on paint stored carelessly in a cupboard. Later they were told that the cupboard had in fact been empty. Most remembered the correction, yet many still mentioned the paint when asked to explain the fire. Corrections work better when they do more than deny the claim, and especially when they offer an alternative explanation that fills the gap the false story leaves behind.\n\nFor some years it was feared that corrections could make matters worse. Early studies suggested a so-called backfire effect, in which people who were shown evidence against their beliefs held those beliefs even more strongly. Later and larger studies, however, have found this reaction to be rare. In most cases, a clear correction moves people at least a little towards the truth. This is good news, and it suggests that the effort put into checking facts is not wasted.\n\nWho, then, is most likely to believe and share false stories? It is often assumed that the answer is people who are less educated. The evidence is more complicated. What seems to matter more is whether a person stops to think. People who tend to reflect before reacting are better at telling true headlines from false ones, whatever their background. Encouragingly, a simple reminder can have a similar effect. When social media users were asked to consider the accuracy of a single headline before they continued browsing, they went on to share noticeably fewer false stories. The reminder took only a few seconds, and it cost nothing.\n\nAnother promising approach works before a rumour arrives rather than after. Known as prebunking, it involves warning people in advance about the techniques used to mislead them: false experts, invented quotes, images taken out of context. Some researchers have built short online games in which players take the role of someone spreading false stories, and those who play them appear to become better at recognising such tricks in real life. The idea is similar to a vaccine: a small, harmless dose of the method builds resistance to the real thing.\n\nSome argue that the solution is simply for governments to decide which stories are false and to require platforms to remove them. I have serious doubts about this. Deciding what counts as true is not always straightforward, and a power of this kind could easily be used against legitimate criticism. Better design, education and the habit of pausing before we share seem to me far safer foundations.\n\nNone of this will make false rumours disappear. As long as people talk, some of what they say will be wrong, and some of it will be deliberately misleading. But we do not need to stop rumours entirely in order to slow them down, and the research suggests that slowing them down is well within our reach.","groups":[{"instruction":"Questions 27-30. Choose the correct letter, A, B, C or D. Write the correct letter in boxes 27-30 on your answer sheet.","qtype":"mcq","questions":[{"n":27,"kind":"mcq","prompt":"What is the writer’s main point in the first paragraph?","options":["A False rumours are a new problem.","B Automated accounts are mainly responsible.","C The causes lie partly in human behaviour.","D Social media companies are unaware of the problem."],"correct":2,"evidence":"the habits of mind that drive it, however, are our own","why":{"en":"Blaming technology \"would be a mistake\": \"the habits of mind that drive it... are our own\". Rumours are old, and people, not automated accounts, did most of the sharing.","tr":"Teknolojiyi suçlamak \"hata olur\": \"onu yönlendiren zihin alışkanlıkları... bizim\". Söylentiler eski ve paylaşımın çoğunu otomatik hesaplar değil, insanlar yaptı.","fa":"مقصر دانستن فناوری «اشتباه است»: «عادت‌های ذهنی‌ای که آن را جلو می‌برند... مال خود ماست». شایعه قدیمی است و بیشترِ اشتراک‌گذاری را آدم‌ها کردند، نه حساب‌های خودکار."},"trap":["TR-paraphrase","TR-whosevoice"]},{"n":28,"kind":"mcq","prompt":"According to the second paragraph, statements that people have heard several times","options":["A seem more believable, even when people know some may be false.","B are believed only by people who know little about the subject.","C are easier to remember than new statements.","D are less likely to be shared."],"correct":0,"evidence":"even when participants have been told that some of them are false","why":{"en":"Repeated statements feel true \"even when participants have been told that some of them are false\" and even against what they know.","tr":"Tekrarlanan ifadeler, \"katılımcılara bazılarının yanlış olduğu söylendiğinde bile\" ve bildiklerine rağmen doğru gibi geliyor.","fa":"جمله‌های تکراری «حتی وقتی به شرکت‌کننده‌ها گفته شده بعضی‌شان غلط‌اند» و حتی برخلاف دانسته‌هایشان، درست به نظر می‌رسند."},"trap":["TR-paraphrase"]},{"n":29,"kind":"mcq","prompt":"What does the experiment about the fire show?","options":["A People forget corrections very quickly.","B People prefer dramatic explanations to simple ones.","C Most people refuse to accept corrections.","D A correction may not remove the effect of the first explanation."],"correct":3,"evidence":"yet many still mentioned the paint when asked to explain the fire","why":{"en":"They remembered the correction \"yet many still mentioned the paint\": the first explanation kept its influence.","tr":"Düzeltmeyi hatırladılar \"ama yine de birçoğu boyadan söz etti\": ilk açıklama etkisini korudu.","fa":"اصلاحیه را به یاد داشتند، «با این حال خیلی‌ها هنوز از رنگ حرف زدند»: توضیح اول اثرش را حفظ کرد."},"trap":["TR-paraphrase","TR-samewords"]},{"n":30,"kind":"mcq","prompt":"What does the writer say about the \"backfire effect\"?","options":["A It happens more often than people realise.","B Research has found it to be uncommon.","C It explains why checking facts is a waste of effort.","D It mainly affects educated people."],"correct":1,"evidence":"Later and larger studies, however, have found this reaction to be rare","why":{"en":"\"Later and larger studies... have found this reaction to be rare.\" The writer says fact-checking is \"not wasted\".","tr":"\"Daha sonraki ve daha büyük çalışmalar... bu tepkinin nadir olduğunu buldu.\" Yazar doğruluk kontrolünün \"boşa gitmediğini\" söylüyor.","fa":"«پژوهش‌های بعدی و بزرگ‌تر... این واکنش را نادر یافتند». نویسنده می‌گوید زحمت بررسی واقعیت‌ها «هدر نمی‌رود»."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 31-36. Complete the summary using the list of words, A-J, below. Write the correct letter, A-J, in boxes 31-36 on your answer sheet.","qtype":"summary-box","summaryTitle":"Belief, correction and sharing","bank":["A accuracy","B alternative","C educated","D emotional","E influence","F popular","G reflect","H reminder","I repeated","J wealthy"],"questions":[{"n":31,"kind":"match","prompt":"Even after a false claim has been corrected, it may continue to ___ the way people reason.","correct":4,"evidence":"it often continues to influence their reasoning","why":{"en":"\"Continues to influence their reasoning\": influence (E).","tr":"\"Akıl yürütmelerini etkilemeye devam eder\": influence (E).","fa":"«به اثر گذاشتن بر استدلالشان ادامه می‌دهد»: influence (E)."},"trap":["TR-paraphrase"]},{"n":32,"kind":"match","prompt":"A correction works better when it offers an ___ explanation.","correct":1,"evidence":"offer an alternative explanation","why":{"en":"\"Offer an alternative explanation that fills the gap\": alternative (B).","tr":"\"Boşluğu dolduran alternatif bir açıklama sunmak\": alternative (B).","fa":"«توضیح جایگزینی بدهد که جای خالی را پر کند»: alternative (B)."},"trap":["TR-paraphrase"]},{"n":33,"kind":"match","prompt":"Believing false stories is not simply a matter of being less ___;","correct":2,"evidence":"people who are less educated","why":{"en":"\"It is often assumed that the answer is people who are less educated. The evidence is more complicated.\" educated (C).","tr":"\"Çoğu zaman cevabın daha az eğitimli insanlar olduğu varsayılıyor. Kanıtlar daha karmaşık.\" educated (C).","fa":"«اغلب فرض می‌شود جواب آدم‌های کم‌سوادترند. شواهد پیچیده‌ترند». educated (C)."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":34,"kind":"match","prompt":"what matters more is whether people ___ before they react.","correct":6,"evidence":"People who tend to reflect before reacting","why":{"en":"\"People who tend to reflect before reacting are better at telling true headlines from false ones\": reflect (G).","tr":"\"Tepki vermeden önce düşünme eğiliminde olanlar doğru ve yanlış manşetleri daha iyi ayırıyor\": reflect (G).","fa":"«کسانی که پیش از واکنش فکر می‌کنند، تیترهای درست و غلط را بهتر تشخیص می‌دهند»: reflect (G)."},"trap":["TR-paraphrase"]},{"n":35,"kind":"match","prompt":"People share fewer false stories if they are first asked to think about the ___ of a headline.","correct":0,"evidence":"asked to consider the accuracy of a single headline","why":{"en":"\"Asked to consider the accuracy of a single headline\": accuracy (A).","tr":"\"Tek bir manşetin doğruluğunu düşünmeleri istendiğinde\": accuracy (A).","fa":"«وقتی از آن‌ها خواستند درستیِ یک تیتر را بسنجند»: accuracy (A)."},"trap":["TR-paraphrase"]},{"n":36,"kind":"match","prompt":"This simple ___ takes only a few seconds.","correct":7,"evidence":"The reminder took only a few seconds","why":{"en":"\"The reminder took only a few seconds\": reminder (H). Repeated (I) belongs to the second paragraph.","tr":"\"Hatırlatma yalnızca birkaç saniye sürdü\": reminder (H). Repeated (I) ikinci paragrafa ait.","fa":"«یادآوری فقط چند ثانیه طول کشید»: reminder (H). repeated (I) مال پاراگراف دوم است."},"trap":["TR-samewords"]}]},{"instruction":"Questions 37-40. Do the following statements agree with the views of the writer in Reading Passage 3? In boxes 37-40 on your answer sheet, write YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.","qtype":"ynng","questions":[{"n":37,"kind":"ynng","prompt":"Governments should decide which stories are false and require platforms to remove them.","correct":"NO","evidence":"I have serious doubts about this","why":{"en":"The writer has \"serious doubts\", because such power could be used against legitimate criticism.","tr":"Yazarın \"ciddi şüpheleri\" var; çünkü böyle bir güç meşru eleştiriye karşı kullanılabilir.","fa":"نویسنده «تردیدهای جدی» دارد، چون چنین قدرتی ممکن است علیه انتقاد مشروع به کار رود."},"trap":["TR-whosevoice"]},{"n":38,"kind":"ynng","prompt":"Games that show how false stories are made may help people to resist them.","correct":"YES","evidence":"Another promising approach works before a rumour arrives","why":{"en":"The writer calls prebunking \"promising\", and players \"appear to become better at recognising such tricks\".","tr":"Yazar ön-çürütmeye \"umut verici\" diyor; oyuncular \"bu hileleri tanımada daha iyi hâle geliyor gibi\".","fa":"نویسنده پیش‌گیری را «امیدبخش» می‌نامد و بازیکن‌ها «به نظر در تشخیص این ترفندها بهتر می‌شوند»."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":39,"kind":"ynng","prompt":"Social media companies earn more from false stories than from accurate ones.","correct":"NOT GIVEN","evidence":"The platforms have certainly made the problem bigger","why":{"en":"The writer says the platforms made the problem bigger, but nothing about what they earn.","tr":"Yazar platformların sorunu büyüttüğünü söylüyor ama ne kazandıklarından hiç söz etmiyor.","fa":"نویسنده می‌گوید پلتفرم‌ها مشکل را بزرگ‌تر کرده‌اند، اما درباره‌ی درآمدشان چیزی نمی‌گوید."},"trap":["TR-NGvsF"]},{"n":40,"kind":"ynng","prompt":"It will one day be possible to stop false rumours completely.","correct":"NO","evidence":"None of this will make false rumours disappear","why":{"en":"\"None of this will make false rumours disappear\": we can slow them down, not stop them.","tr":"\"Bunların hiçbiri sahte söylentileri yok etmeyecek\": onları yavaşlatabiliriz, durduramayız.","fa":"«هیچ‌کدام از این‌ها شایعه‌های دروغ را از بین نمی‌برد»: می‌شود کُندشان کرد، نه متوقفشان."},"trap":["TR-whosevoice"]}]}],"id":"c-x09-r3-d","course":"ielts-exams","exam":"exam-09","unit":"x09-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The study found this reaction to be rare.\" Rare means...","options":["not common","very strong","easy to explain"],"correct":0,"why":{"en":"Rare = seldom happening, uncommon.","tr":"Rare = nadir, seyrek.","fa":"rare یعنی نادر، کم‌پیش‌آمد."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase in a passage shows the writer’s own view?","options":["Some argue that","It is often assumed that","I have serious doubts about this"],"correct":2,"why":{"en":"\"I have serious doubts\" is the writer speaking; the others report other people’s ideas.","tr":"\"Ciddi şüphelerim var\" yazarın kendisi; diğerleri başkalarının fikirlerini aktarıyor.","fa":"«تردید جدی دارم» صدای خود نویسنده است؛ بقیه فکر دیگران را نقل می‌کنند."}},{"tests":"method","point":2,"prompt":"In a summary with a word box, two words both fit the grammar of a gap. How do you choose?","options":["Choose the one that comes first in the box","Check which one matches the meaning of the passage","Choose the longer word"],"correct":1,"why":{"en":"Grammar narrows the choice; meaning decides it.","tr":"Dilbilgisi seçeneği daraltır; anlam karar verir.","fa":"دستور زبان انتخاب را محدود می‌کند؛ معنی تصمیم را می‌گیرد."}},{"tests":"trap","point":3,"prompt":"Text: \"Many parents think homework improves results. The research is mixed.\" Statement: \"The writer believes homework improves results.\"","options":["NOT GIVEN","YES","NO"],"correct":0,"why":{"en":"The parents’ belief is reported, and the research is \"mixed\"; the writer gives no view of their own.","tr":"Ebeveynlerin inancı aktarılıyor ve araştırma \"karışık\"; yazar kendi görüşünü vermiyor.","fa":"باور پدر و مادرها نقل می‌شود و پژوهش «ضدونقیض» است؛ نویسنده نظر خودش را نمی‌دهد."}}],"id":"c-x09-r3-x","course":"ielts-exams","exam":"exam-09","unit":"x09-r3"},"gt":{"explain":{"title":{"en":"GT Reading Section 3: a long article","tr":"GT Reading Section 3: uzun bir makale","fa":"GT Reading Section 3: یک مقاله‌ی بلند"},"objective":{"en":"In this lesson you will learn to choose a heading for each paragraph of a long article, complete a summary with one word from the text, and answer multiple choice questions.","tr":"Bu derste uzun bir makalenin her paragrafına bir başlık seçmeyi, bir özeti metinden tek kelimeyle tamamlamayı ve çoktan seçmeli soruları cevaplamayı öğreneceksin.","fa":"در این درس یاد می‌گیری برای هر پاراگراف یک مقاله‌ی بلند عنوان انتخاب کنی، یک خلاصه را با یک کلمه از متن کامل کنی و به سؤال‌های چندگزینه‌ای جواب بدهی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Paragraphs","tr":"Paragraf","fa":"پاراگراف"},"value":"A-E"},{"label":{"en":"Headings","tr":"Başlık","fa":"عنوان"},"value":"i-viii"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: texting and spelling","tr":"Bu sınav: mesajlaşma ve yazım","fa":"این آزمون: پیامک و املا"},"intro":{"en":"GT Section 3 is one long article on a general topic. Society, work and daily life are among the most frequent subjects; here the article tests a popular worry against the evidence.","tr":"GT Section 3 genel bir konuda tek bir uzun makaledir. Toplum, iş ve gündelik hayat en sık çıkan konulardandır; burada makale yaygın bir kaygıyı kanıtlarla sınıyor.","fa":"GT Section 3 یک مقاله‌ی بلند درباره‌ی موضوعی عمومی است. جامعه، کار و زندگی روزمره از پرتکرارترین موضوع‌هایند؛ این‌جا مقاله یک نگرانی رایج را با شواهد می‌سنجد."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x09-r3gt-ctx","exam":true,"patterns":["GT3-life"],"often":{"pattern":"GT3-life","n":14,"of":40,"label":{"en":"Comes up often in the real exam: 14 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 14’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۴ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"An article on language and everyday life","tr":"Dil ve gündelik hayat üzerine bir makale","fa":"مقاله‌ای درباره‌ی زبان و زندگی روزمره"},"asks":{"en":"A general-interest article in five paragraphs looks at a popular worry about modern life, what research says, how the situation compares with the past, what is changing now and what the real skill is. You choose paragraph headings, complete a summary and answer three questions.","tr":"Beş paragraflık genel ilgi çeken bir makale modern hayatla ilgili yaygın bir kaygıyı inceliyor: araştırmaların ne dediğini, durumun geçmişle nasıl karşılaştırıldığını, şimdi neyin değiştiğini ve asıl becerinin ne olduğunu. Paragraf başlıkları seçiyor, bir özeti tamamlıyor ve üç soruyu cevaplıyorsun.","fa":"یک مقاله‌ی عمومی در پنج پاراگراف یک نگرانی رایج درباره‌ی زندگی امروز را بررسی می‌کند: پژوهش‌ها چه می‌گویند، وضع با گذشته چه فرقی دارد، الان چه چیزی عوض می‌شود و مهارت واقعی چیست. عنوان پاراگراف‌ها را انتخاب می‌کنی، یک خلاصه را کامل می‌کنی و به سه سؤال جواب می‌دهی."},"fields":["The worry","The research","The past","What is changing now","The real skill"],"words":[{"a":"a concern","b":"a worry / a fear","tr":"kaygı","fa":"نگرانی"},{"a":"widespread","b":"common / shared by many","tr":"yaygın","fa":"گسترده"},{"a":"reassuring","b":"makes you less worried","tr":"içi rahatlatan","fa":"اطمینان‌بخش"},{"a":"abbreviation","b":"a short form of a word","tr":"kısaltma","fa":"کوته‌نوشت"},{"a":"far from new","b":"has happened before / not a recent thing","tr":"hiç de yeni değil","fa":"اصلاً تازه نیست"},{"a":"disappearing","b":"becoming less common","tr":"kayboluyor","fa":"در حال از بین رفتن"},{"a":"punctuation","b":"full stops, commas, capital letters","tr":"noktalama","fa":"نشانه‌گذاری"},{"a":"appropriate","b":"right for the situation","tr":"uygun","fa":"مناسب"},{"a":"move between styles","b":"switch / write one way here, another way there","tr":"üsluplar arasında geçiş yapmak","fa":"بین سبک‌ها جابه‌جا شدن"},{"a":"conventions","b":"rules / accepted ways of doing something","tr":"gelenekler, kurallar","fa":"قواعد پذیرفته‌شده"}],"traps":[{"en":"One heading may match a single example in a paragraph (\"the cost of sending messages\") but not its main idea.","tr":"Bir başlık paragraftaki tek bir örneğe (\"mesaj gönderme maliyeti\") uyabilir ama ana fikrine uymaz.","fa":"یک عنوان ممکن است با یک مثالِ داخل پاراگراف جور باشد («هزینه‌ی فرستادن پیام») اما نه با ایده‌ی اصلی‌اش."},{"en":"A heading can say the opposite of the text (\"Why teachers no longer worry\") while using the same topic words.","tr":"Bir başlık aynı konu kelimelerini kullanırken metnin tersini söyleyebilir (\"Öğretmenler neden artık endişelenmiyor\").","fa":"یک عنوان ممکن است با همان کلمه‌های موضوع، برعکسِ متن را بگوید («چرا معلم‌ها دیگر نگران نیستند»)."}],"example":{"text":"\"Shops once closed on Sundays by law. When the rules changed in the 1990s, supermarkets were the first to open, and small shops soon followed.\"","item":"Best heading: A Why small shops closed  B The end of Sunday closing","answer":"B","why":{"en":"The paragraph is about the change in the law and what followed; small shops opened, they did not close.","tr":"Paragraf yasa değişikliği ve ardından olanlarla ilgili; küçük dükkânlar kapanmadı, açıldı.","fa":"پاراگراف درباره‌ی تغییر قانون و اتفاق‌های بعدش است؛ مغازه‌های کوچک بسته نشدند، باز شدند."}}},{"id":"GT3-life","ctx":["GT3-life"],"title":{"en":"Society, work and daily life","tr":"Toplum, iş ve gündelik yaşam","fa":"جامعه، کار و زندگی روزمره"},"asks":{"en":"A text about modern life, work or society: a nursery without toys, emojis, a health programme, lessons in leadership, life in a cold town. Headings and multiple choice test the writer’s main points.","tr":"Modern yaşam, iş ya da toplum hakkında bir metin: oyuncaksız bir kreş, emojiler, bir sağlık programı, liderlik dersleri, soğuk bir kasabada yaşam. Başlıklar ve çoktan seçmeli sorular yazarın ana noktalarını sınar.","fa":"متنی درباره‌ی زندگی امروز، کار یا جامعه: مهدکودکی بدون اسباب‌بازی، ایموجی‌ها، یک برنامه‌ی سلامت، درس‌هایی درباره‌ی رهبری، زندگی در یک شهر سرد. عنوان‌ها و سؤال‌های چندگزینه‌ای نکته‌های اصلی نویسنده را می‌سنجند."},"fields":["An experiment that surprised parents","Mixed reactions from staff","The original purpose","Plans to expand the scheme","Which paragraph describes the results after a year?"],"words":[{"a":"scheme","b":"programme / project","tr":"program, uygulama","fa":"طرح"},{"a":"reaction","b":"response / what people thought","tr":"tepki","fa":"واکنش"},{"a":"mixed","b":"some liked it, others did not","tr":"karışık","fa":"دوگانه"},{"a":"surprising","b":"unexpected / few predicted it","tr":"şaşırtıcı","fa":"غافلگیرکننده"},{"a":"purpose","b":"aim / designed to","tr":"amaç","fa":"هدف"},{"a":"expand","b":"grow / extend to more places","tr":"genişletmek","fa":"گسترش دادن"},{"a":"residents","b":"locals / people who live there","tr":"sakinler","fa":"ساکنان"},{"a":"wellbeing","b":"health and happiness","tr":"iyi oluş","fa":"سلامت و رضایت"},{"a":"communicate","b":"express / get a message across","tr":"iletişim kurmak","fa":"ارتباط برقرار کردن"},{"a":"encourage","b":"motivate / persuade","tr":"teşvik etmek","fa":"تشویق کردن"},{"a":"trend","b":"something becoming common","tr":"eğilim","fa":"روند"},{"a":"outcome","b":"result / what happened","tr":"sonuç","fa":"نتیجه"}],"traps":[{"en":"\"Mixed reactions\" needs both sides in the paragraph. One positive comment is not enough.","tr":"\"Karışık tepkiler\" için paragrafta iki taraf da olmalı. Tek bir olumlu yorum yetmez.","fa":"«واکنش‌های دوگانه» یعنی هر دو طرف در پاراگراف باشند. یک نظر مثبت کافی نیست."},{"en":"The purpose of a scheme and its result are often in different paragraphs.","tr":"Bir uygulamanın amacı ve sonucu çoğu zaman farklı paragraflardadır.","fa":"هدف یک طرح و نتیجه‌اش اغلب در پاراگراف‌های جدا هستند."}],"example":{"text":"E  Not everyone was convinced. Several parents worried that their children would be bored without toys, while a few teachers felt the experiment had started too quickly. Others, however, praised the calmer atmosphere.","item":"Choose the heading for paragraph E:  i  Mixed reactions   ii  Children become bored   iii  How the toys were chosen","answer":"i","why":{"en":"Worries from parents and teachers, then praise from others: both sides, so mixed reactions.","tr":"Ebeveyn ve öğretmenlerin endişeleri, ardından başkalarının övgüsü: iki taraf da var, yani karışık tepkiler.","fa":"نگرانی پدر و مادرها و معلم‌ها، بعد تعریف دیگران: هر دو طرف هست، پس واکنش‌های دوگانه."}},"track":"gt","general":true,"patterns":["GT3-life"],"often":{"pattern":"GT3-life","n":14,"of":40,"label":{"en":"Comes up often in the real exam: 14 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 14’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۴ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Headings, summary, choices","tr":"Başlıklar, özet, seçimler","fa":"عنوان‌ها، خلاصه، گزینه‌ها"},"body":{"en":"Questions 28-32: choose the right heading, i-viii, for paragraphs A-E; three headings are not used. Questions 33-37: complete a summary with ONE WORD ONLY from the text. Questions 38-40: choose A, B, C or D.","tr":"Soru 28-32: A-E paragrafları için doğru başlığı (i-viii) seç; üç başlık kullanılmaz. Soru 33-37: bir özeti metinden YALNIZCA BİR KELİMEYLE tamamla. Soru 38-40: A, B, C ya da D’yi seç.","fa":"سؤال‌های ۲۸ تا ۳۲: برای پاراگراف‌های A تا E عنوان درست (i تا viii) را انتخاب کن؛ سه عنوان استفاده نمی‌شوند. سؤال‌های ۳۳ تا ۳۷: خلاصه را فقط با یک کلمه از متن کامل کن. سؤال‌های ۳۸ تا ۴۰: A، B، C یا D را انتخاب کن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Headings in four steps","tr":"Dört adımda başlıklar","fa":"عنوان‌ها در چهار قدم"},"steps":[{"en":"Read all eight headings first and note the key idea of each.","tr":"Önce sekiz başlığın hepsini oku ve her birinin ana fikrini not et.","fa":"اول هر هشت عنوان را بخوان و ایده‌ی کلیدی هرکدام را یادداشت کن."},{"en":"Read one paragraph and say its main idea in five words.","tr":"Bir paragraf oku ve ana fikrini beş kelimeyle söyle.","fa":"یک پاراگراف بخوان و ایده‌ی اصلی‌اش را در پنج کلمه بگو."},{"en":"Choose the heading that covers the whole paragraph, not one sentence.","tr":"Tek bir cümleyi değil, bütün paragrafı kapsayan başlığı seç.","fa":"عنوانی را انتخاب کن که کل پاراگراف را پوشش بدهد، نه یک جمله را."},{"en":"Cross out headings as you use them, and come back to any paragraph you are unsure about.","tr":"Kullandıkça başlıkların üstünü çiz ve emin olmadığın paragrafa sonra dön.","fa":"عنوان‌ها را وقتی استفاده کردی خط بزن و به پاراگرافی که مطمئن نیستی بعداً برگرد."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"A shared word is not the main idea","tr":"Ortak kelime ana fikir değil","fa":"کلمه‌ی مشترک ایده‌ی اصلی نیست"},"body":{"en":"Wrong headings often borrow a word from the paragraph: \"dam\", \"farmers\", \"museum\". Ask what the paragraph is mainly about, then check the heading says that.","tr":"Yanlış başlıklar çoğu zaman paragraftan bir kelime ödünç alır: \"dam\", \"farmers\", \"museum\". Paragrafın esas olarak ne hakkında olduğunu sor, sonra başlığın bunu söyleyip söylemediğine bak.","fa":"عنوان‌های غلط اغلب کلمه‌ای از پاراگراف قرض می‌گیرند: «dam»، «farmers»، «museum». بپرس پاراگراف اصولاً درباره‌ی چیست و بعد ببین عنوان همین را می‌گوید یا نه."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One heading, step by step","tr":"Bir başlık, adım adım","fa":"یک عنوان، قدم به قدم"},"instruction":"Choose the correct heading for the paragraph.","text":"\"Many people expected online shopping to empty the high street. Surveys show something different: town centres now have more cafés, gyms and hairdressers than ever, even though clothes shops have closed. Rents have fallen in some places, which has helped.\"","item":"Headings: i Falling rents  ii How town centres have changed  iii The end of shopping","answer":"ii","walk":[{"en":"Main idea in five words: town centres changed, not died.","tr":"Beş kelimeyle ana fikir: şehir merkezleri ölmedi, değişti.","fa":"ایده‌ی اصلی در پنج کلمه: مرکز شهرها نمردند، عوض شدند."},{"en":"i is one detail at the end; iii is the expectation the paragraph rejects.","tr":"i sondaki bir ayrıntı; iii paragrafın reddettiği beklenti.","fa":"i یک جزئیات در آخر است؛ iii انتظاری است که پاراگراف ردش می‌کند."},{"en":"ii covers the cafés, gyms and closed shops: the change.","tr":"ii kafeleri, spor salonlarını ve kapanan dükkânları kapsıyor: değişim.","fa":"ii کافه‌ها، باشگاه‌ها و مغازه‌های بسته را پوشش می‌دهد: تغییر."}]},"quick":{"prompt":"A paragraph explains why many people fear robots will take their jobs, quoting workers and a newspaper survey. Which heading fits best?","options":["How robots are built","Newspapers and their readers","A common worry about work"],"correct":2,"why":{"en":"The paragraph is about a fear many people share; the survey is only support.","tr":"Paragraf birçok insanın paylaştığı bir korkuyla ilgili; anket yalnızca destek.","fa":"پاراگراف درباره‌ی ترسی است که خیلی‌ها دارند؛ نظرسنجی فقط پشتوانه است."}},"remember":{"en":"A heading names the main idea of the whole paragraph; ignore headings that only repeat a word.","tr":"Başlık bütün paragrafın ana fikrini söyler; yalnızca bir kelimeyi tekrarlayan başlıklara aldanma.","fa":"عنوان ایده‌ی اصلی کل پاراگراف را می‌گوید؛ فریب عنوان‌هایی را که فقط یک کلمه را تکرار می‌کنند نخور."},"type":"explain","id":"c-x09-r3-e-gt","course":"ielts-exams","exam":"exam-09","unit":"x09-r3"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 3","title":{"en":"Is texting ruining our spelling?","tr":"Mesajlaşma yazımımızı bozuyor mu?","fa":"آیا پیامک املای ما را خراب می‌کند؟"},"timed":20,"ctx":["GT3-life"],"texts":[{"title":"Is texting ruining our spelling?","kind":"article","body":"A  Ever since mobile phones became common, parents and teachers have worried about the effect of text messages on young people's writing. Newspaper articles have warned that a generation raised on short forms such as \"u\" for \"you\" and \"2nite\" for \"tonight\" would never learn to spell properly, and some teachers have reported finding text-style abbreviations in school essays. The fear is easy to understand. If children spend hours every day writing in a careless, shortened style, it seems only natural that the habit will spread to the rest of their writing. Some commentators went further, claiming that texting would weaken young people's ability to concentrate on long texts and to express complex ideas. Employers, too, have occasionally complained about job applications written in a style that looked more like a message to a friend than a letter to a company.\n\nB  Over the past twenty years, however, researchers have tested this idea, and the results have been surprisingly reassuring. Studies that compared children's texting habits with their performance in spelling tests have found no evidence of harm. In several cases, the opposite was true: children who used more abbreviations in their messages tended to be slightly better spellers. One explanation is that inventing a short form is not as easy as it looks. To write \"gr8\" for \"great\", you need to understand how the sounds of a word relate to its letters, and that knowledge of sounds is exactly what good spelling depends on. Children who play with language in this way may actually be practising the skills that teachers want them to learn. Researchers are careful to point out that texting does not make children good spellers on its own; children who already read widely are also more likely to enjoy playing with words. But the studies do suggest that texting is not the threat it was once thought to be.\n\nC  It is also worth remembering that shortened writing is far from new. In the nineteenth century, telegrams were charged by the word, so senders squeezed their messages into as few words as possible, dropping articles and inventing abbreviations. Shorthand, a system of symbols that allowed secretaries and journalists to write as fast as people spoke, was taught in schools for generations. Even older are the puzzles that Victorian readers enjoyed, in which letters and numbers stood for whole words. Each of these was criticised in its time, and none of them destroyed the language. Indeed, some abbreviations that began as shortcuts, such as \"ad\" for \"advertisement\" and \"phone\" for \"telephone\", are now so normal that few people remember they were ever considered lazy.\n\nD  In any case, the abbreviations that worried people so much are now disappearing. When phones had small number keys, typing each letter was slow, and short forms saved real effort, and many networks also charged by the message, which encouraged people to fit as much as possible into each one. Since phones gained full keyboards and automatic correction, most young people simply write words in full. What has changed instead is punctuation. Many younger writers use few capital letters and rarely end a message with a full stop, because in a quick exchange of texts a full stop can seem cold or even unfriendly. Linguists who study these messages argue that this is not carelessness but a new set of rules, understood by the people who use them. A message that ends with a full stop, they point out, may be read by a teenager as a sign that the writer is annoyed, while an older reader may notice nothing at all.\n\nE  The most important skill, many experts now believe, is not avoiding informal writing but knowing when it is appropriate. Surveys of students' writing suggest that most young people move easily between styles, writing one way to a friend and quite another in an exam or a job application, in the same way that people speak differently at home and at work. Problems arise mainly when writers are unsure which style a situation requires. For this reason, some teachers now bring text messages into the classroom, asking students to compare them with formal letters and to rewrite one in the style of the other. Rather than treating texting as an enemy of good writing, they use it to show that every kind of writing has its own conventions, and that skilled writers can choose between them. The aim, as one teacher put it, is not to stop students texting, but to make sure they never send a job application that reads like a text."}],"groups":[{"text":0,"instruction":"Questions 28-32. The text has five paragraphs, A-E. Choose the correct heading for each paragraph from the list of headings below. Write the correct number, i-viii, in boxes 28-32 on your answer sheet.","qtype":"headings","bank":["i The cost of sending messages","ii Choosing the right style for the situation","iii A widespread concern","iv Why teachers no longer worry","v Short forms in earlier times","vi What studies have shown","vii Phones banned from classrooms","viii New habits in punctuation"],"questions":[{"n":28,"kind":"match","prompt":"Paragraph A","correct":2,"evidence":"parents and teachers have worried about the effect of text messages","why":{"en":"A is about the fear that texting harms spelling: a widespread concern.","tr":"A, mesajlaşmanın yazımı bozduğu korkusuyla ilgili: yaygın bir kaygı.","fa":"A درباره‌ی ترس از آسیب پیامک به املاست: نگرانیِ گسترده."},"trap":["TR-detail"]},{"n":29,"kind":"match","prompt":"Paragraph B","correct":5,"evidence":"researchers have tested this idea","why":{"en":"B reports what the studies found.","tr":"B araştırmaların ne bulduğunu anlatıyor.","fa":"B گزارش می‌دهد پژوهش‌ها چه یافتند."},"trap":["TR-detail"]},{"n":30,"kind":"match","prompt":"Paragraph C","correct":4,"evidence":"shortened writing is far from new","why":{"en":"C: telegrams, shorthand and puzzles = short forms in earlier times. Telegram costs are only one example, so i is wrong.","tr":"C: telgraflar, stenografi ve bulmacalar = eski zamanlarda kısaltmalar. Telgraf ücreti yalnızca bir örnek; i yanlış.","fa":"C: تلگراف، تندنویسی و معما یعنی شکل‌های کوتاه‌شده در گذشته. هزینه‌ی تلگراف فقط یک مثال است، پس i غلط است."},"trap":["TR-samewords","TR-detail"]},{"n":31,"kind":"match","prompt":"Paragraph D","correct":7,"evidence":"What has changed instead is punctuation","why":{"en":"D: abbreviations disappear, and the new thing is punctuation (capitals, full stops).","tr":"D: kısaltmalar kayboluyor; yeni olan noktalama (büyük harfler, noktalar).","fa":"D: کوته‌نوشت‌ها از بین می‌روند و چیز تازه نشانه‌گذاری است (حرف بزرگ، نقطه)."},"trap":["TR-samewords"]},{"n":32,"kind":"match","prompt":"Paragraph E","correct":1,"evidence":"knowing when it is appropriate","why":{"en":"E: the skill is knowing which style fits the situation.","tr":"E: beceri, duruma hangi üslubun uyduğunu bilmek.","fa":"E: مهارت این است که بدانی کدام سبک به موقعیت می‌خورد."},"trap":["TR-detail"]}]},{"text":0,"instruction":"Questions 33-37. Complete the summary below. Choose ONE WORD ONLY from the text for each answer.","qtype":"summary","summaryTitle":"Texting and writing","questions":[{"n":33,"kind":"gap","prompt":"Studies found that texting did not cause any ___ to children’s spelling.","accept":["harm"],"limit":1,"evidence":"have found no evidence of harm","why":{"en":"\"No evidence of harm\" = texting did not cause harm.","tr":"\"Zarar gördüğüne dair kanıt yok\".","fa":"«هیچ شاهدی از آسیب پیدا نکردند»."},"trap":["TR-paraphrase"]},{"n":34,"kind":"gap","prompt":"Making up short forms requires an understanding of ___.","accept":["sounds"],"limit":1,"evidence":"that knowledge of sounds is exactly what good spelling depends on","why":{"en":"\"Understand how the sounds of a word relate to its letters\". Plural.","tr":"\"Bir kelimenin seslerinin harfleriyle ilişkisini anlamak\". Çoğul.","fa":"«فهمیدن رابطه‌ی صداهای کلمه با حرف‌هایش». جمع."},"trap":["TR-plural"]},{"n":35,"kind":"gap","prompt":"Short forms became less common when phones gained full ___.","accept":["keyboards"],"limit":1,"evidence":"Since phones gained full keyboards","why":{"en":"\"Since phones gained full keyboards and automatic correction\". Plural.","tr":"\"Telefonlar tam klavye ve otomatik düzeltme kazandığından beri\". Çoğul.","fa":"«از وقتی گوشی‌ها صفحه‌کلید کامل و اصلاح خودکار پیدا کردند». جمع."},"trap":["TR-plural"]},{"n":36,"kind":"gap","prompt":"Many young people avoid ending a message with a full stop, which can seem ___.","accept":["unfriendly","cold"],"limit":1,"evidence":"a full stop can seem cold or even unfriendly","why":{"en":"\"Cold or even unfriendly\": both words are in the text and either fits the gap.","tr":"\"Soğuk, hatta düşmanca\": iki kelime de metinde var ve ikisi de boşluğa uyar.","fa":"«سرد یا حتی غیردوستانه»: هر دو کلمه در متن هستند و هر کدام در جای خالی می‌نشیند."},"trap":["TR-paraphrase"]},{"n":37,"kind":"gap","prompt":"Some teachers ask students to ___ a text message in a formal style.","accept":["rewrite"],"limit":1,"evidence":"to rewrite one in the style of the other","why":{"en":"\"Rewrite one in the style of the other\". Copy the verb.","tr":"\"Birini öbürünün üslubunda yeniden yazmak\". Fiili kopyala.","fa":"«یکی را به سبک دیگری بازنویسی کنند». فعل را کپی کن."},"trap":["TR-limit"]}]},{"text":0,"instruction":"Questions 38-40. Choose the correct letter, A, B, C or D.","qtype":"mcq","questions":[{"n":38,"kind":"mcq","prompt":"Why were nineteenth-century telegrams written in a short style?","options":["A They were sent by secretaries.","B Long messages were not allowed.","C Senders paid for each word.","D Shorthand was taught in schools."],"correct":2,"evidence":"telegrams were charged by the word","why":{"en":"\"Telegrams were charged by the word\", so senders used as few words as possible.","tr":"\"Telgraflar kelime başına ücretlendiriliyordu\", bu yüzden gönderenler mümkün olduğunca az kelime kullanıyordu.","fa":"«هزینه‌ی تلگراف کلمه‌ای حساب می‌شد»، پس فرستنده‌ها تا جایی که می‌شد کلمه‌ی کمتری می‌نوشتند."},"trap":["TR-paraphrase"]},{"n":39,"kind":"mcq","prompt":"According to the writer, why are text abbreviations less common now?","options":["A Phones make it easy to type whole words.","B Teachers have banned them.","C Young people send fewer messages.","D Employers have complained about them."],"correct":0,"evidence":"most young people simply write words in full","why":{"en":"With full keyboards and automatic correction, typing whole words is easy, so short forms no longer save effort.","tr":"Tam klavye ve otomatik düzeltmeyle bütün kelimeleri yazmak kolay; kısaltmalar artık zaman kazandırmıyor.","fa":"با صفحه‌کلید کامل و اصلاح خودکار، نوشتن کلمه‌ی کامل آسان است، پس کوته‌نوشت دیگر زحمتی کم نمی‌کند."},"trap":["TR-paraphrase","TR-samewords"]},{"n":40,"kind":"mcq","prompt":"What is the writer’s main purpose in the article?","options":["A to describe the history of shorthand","B to persuade schools to ban phones","C to explain how to write a formal letter","D to show that fears about texting and spelling are largely unfounded"],"correct":3,"evidence":"the results have been surprisingly reassuring","why":{"en":"The article answers the worry in A with research, history and current habits: the fear is largely unfounded.","tr":"Makale A’daki kaygıyı araştırma, tarih ve bugünkü alışkanlıklarla cevaplıyor: korku büyük ölçüde temelsiz.","fa":"مقاله نگرانیِ A را با پژوهش، تاریخ و عادت‌های امروز جواب می‌دهد: ترس تا حد زیادی بی‌پایه است."},"trap":["TR-paraphrase"]}]}],"id":"c-x09-r3-d-gt","course":"ielts-exams","exam":"exam-09","unit":"x09-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The results were reassuring.\" This means they...","options":["made people more worried","made people less worried","were difficult to understand"],"correct":1,"why":{"en":"Reassuring = making you feel less anxious.","tr":"Reassuring = içini rahatlatan.","fa":"reassuring یعنی اطمینان‌بخش، کم‌کننده‌ی نگرانی."}},{"tests":"paraphrase","point":1,"prompt":"Which heading means the same as \"Short forms in earlier times\"?","options":["Abbreviations in the past","The future of spelling","Why we write less"],"correct":0,"why":{"en":"Short forms = abbreviations; earlier times = the past.","tr":"Short forms = kısaltmalar; earlier times = geçmiş.","fa":"short forms یعنی کوته‌نوشت؛ earlier times یعنی گذشته."}},{"tests":"method","point":2,"prompt":"Five paragraphs and eight headings. How many headings are not used?","options":["none","five","three"],"correct":2,"why":{"en":"Eight minus five leaves three unused headings.","tr":"Sekizden beş çıkınca üç başlık kullanılmadan kalır.","fa":"هشت منهای پنج، سه عنوانِ استفاده‌نشده می‌ماند."}},{"tests":"trap","point":3,"prompt":"A paragraph is about how a festival began, and mentions that tickets were cheap. Heading \"The price of tickets\". Is it right?","options":["Yes: tickets are mentioned","No: it matches only one detail","Only if the paragraph is short"],"correct":1,"why":{"en":"A heading must cover the main idea, not one detail.","tr":"Başlık tek bir ayrıntıyı değil, ana fikri kapsamalı.","fa":"عنوان باید ایده‌ی اصلی را پوشش بدهد، نه یک جزئیات را."}}],"id":"c-x09-r3-x-gt","course":"ielts-exams","exam":"exam-09","unit":"x09-r3"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
